1:'use strict';
2:const { toObjects } = require('./rows');
3:
4:/**
5: * Create an incremental CSV parser; options is an optional object.
6: *
7: * delimiter defaults to ',' when omitted or undefined. It must be a string of
8: * length 1 (one UTF-16 code unit), other than '"', '\r', or '\n'; otherwise throw
9: * RangeError at creation. No trimming, coercion, or delimiter auto-detection.
10: *
11: * push(chunk) accepts only strings (otherwise TypeError). It returns string[][]
12: * containing ONLY the records completed by this call, in order, never records
13: * returned by an earlier call. A record is completed immediately at an outside-
14: * quote LF or CR, even if the LF of a CRLF has not arrived yet. An unfinished
15: * record stays buffered. Empty chunks do nothing, including before a BOM.
16: *
17: * end() finishes input and returns the last record if input has an unfinished
18: * one; otherwise returns []. Calling end again returns []. Any push after end,
19: * even push(''), throws Error. Separate parsers have independent state.
20: *
21: * CSV grammar:
22: * - A delimiter ends a field. Empty fields, including trailing ones, are kept.
23: * - '"' opens a quoted field only as the FIRST character of a field. Quotes in
24: *   an unquoted field are literal characters, not an error or a quoting toggle.
25: * - In a quoted field, '""' produces one literal '"'. Delimiters, CR, LF, and
26: *   CRLF inside quotes are preserved exactly, not normalized or treated as
27: *   separators. The next '"' not part of a doubled quote closes the field.
28: * - After a closing quote only delimiter, LF, CR, or EOF is legal. Any other
29: *   character, including whitespace, throws SyntaxError during push().
30: * - Outside quotes, LF, CRLF, and lone CR end records. CRLF is ONE separator,
31: *   even across chunks. Every separator emits the current row, even if empty:
32: *   '\n' is [['']], '\n\n' is [[''], ['']], and 'a\n' is [['a']]. EOF after a
33: *   separator adds nothing. Empty input or BOM-only input produces [].
34: * - Strip one U+FEFF BOM only if it is the first character of all input. Later
35: *   BOMs are ordinary field data. A BOM is supplied as a whole character.
36: *
37: * Every SyntaxError message contains 'line N', where N is the 1-based PHYSICAL
38: * line at the offending character, or the line at EOF for an unterminated quote.
39: * Count CR and LF inside quoted fields too; each CRLF counts as one newline,
40: * regardless of chunk boundaries. A lone CR or LF counts as one newline.
41: * end() throws SyntaxError for an unterminated quoted field. No recovery behavior
42: * is required after a SyntaxError. Chunk boundaries may otherwise fall anywhere,
43: * including inside an escaped '""', CRLF, or a Unicode surrogate pair.
44: *
45: * options.header does not affect this streaming API: it always yields arrays.
46: * @param {{ delimiter?: string, header?: boolean }} [options]
47: * @returns {{ push(chunk: string): string[][], end(): string[][] }}
48: */
49:function createParser(options = {}) {
50:  throw new Error('not implemented');
51:}
52:
53:/**
54: * Parse all text using the same grammar and validation as createParser.
55: * With options.header === true, convert records with the existing
56: * toObjects(records, { header: true }) helper; otherwise return string[][].
57: * Empty input yields [] in either mode. Do not change the helper's contract.
58: */
59:function parse(text, options = {}) {
60:  const parser = createParser(options);
61:  const records = parser.push(text).concat(parser.end());
62:  return options.header === true ? toObjects(records, { header: true }) : records;
63:}
64:
65:module.exports = { createParser, parse };

