+function createParser(options = {}) {
+  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
+  if (typeof delimiter !== 'string' || delimiter.length !== 1 ||
+      delimiter === '"' || delimiter === '\r' || delimiter === '\n') {
+    throw new RangeError('delimiter must be one character other than \'"\', CR, or LF');
+  }
+
+  // FIELD_START: at the start of a field; UNQUOTED: inside an unquoted field;
+  // QUOTED: inside a quoted field; QUOTE: saw '"' in a quoted field (escape or close).
+  const FIELD_START = 0;
+  const UNQUOTED = 1;
+  const QUOTED = 2;
+  const QUOTE = 3;
+
+  let state = FIELD_START;
+  let row = [];
+  let field = '';
+  let inRecord = false; // any character of the current record consumed
+  let lastWasCR = false; // previous code unit (anywhere) was CR
+  let line = 1;
+  let started = false;
+  let ended = false;
+
+  function endField() {
+    row.push(field);
+    field = '';
+    state = FIELD_START;
+  }
+
+  function endRecord(out) {
+    endField();
+    out.push(row);
+    row = [];
+    inRecord = false;
+  }
+
+  function push(chunk) {
+    if (ended) throw new Error('push() called after end()');
+    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
+    const out = [];
+    if (chunk.length === 0) return out;
+    let i = 0;
+    if (!started) {
+      started = true;
+      if (chunk.charCodeAt(0) === 0xfeff) i = 1;
+    }
+    for (; i < chunk.length; i++) {
+      const ch = chunk[i];
+      const isCR = ch === '\r';
+      const isLF = ch === '\n';
+      const crlfTail = isLF && lastWasCR;
+      lastWasCR = isCR;
+
+      if (state === QUOTED) {
+        if (ch === '"') state = QUOTE;
+        else field += ch;
+        if (isCR || (isLF && !crlfTail)) line++;
+        continue;
+      }
+
+      if (state === QUOTE) {
+        if (ch === '"') {
+          field += '"';
+          state = QUOTED;
+          continue;
+        }
+        if (ch !== delimiter && !isCR && !isLF) {
+          throw new SyntaxError(`Unexpected character after closing quote at line ${line}`);
+        }
+        // Closed quoted field: fall through to separator handling below.
+      }
+
+      if (isCR || isLF) {
+        if (crlfTail) continue; // LF of a CRLF whose CR already ended the record
+        line++;
+        endRecord(out);
+      } else if (ch === delimiter) {
+        inRecord = true;
+        endField();
+      } else if (state === FIELD_START && ch === '"') {
+        inRecord = true;
+        state = QUOTED;
+      } else {
+        inRecord = true;
+        field += ch;
+        state = UNQUOTED;
+      }
+    }
+    return out;
+  }
+
+  function end() {
+    if (ended) return [];
+    ended = true;
+    if (state === QUOTED) {
+      throw new SyntaxError(`Unterminated quoted field at line ${line}`);
+    }
+    const out = [];
+    if (inRecord) endRecord(out);
+    return out;
+  }
+
+  return { push, end };
+}

